mapper.insert:
INSERT INTO T_MOCK_ACCOUNT (
       USER_ID
      ,CASH
      ,INIT_CASH
) VALUES (
       #{userId}
      ,#{initCash}
      ,#{initCash}
)
ON CONFLICT (USER_ID) DO NOTHING

mapper.update:
UPDATE T_MOCK_ACCOUNT
   SET CASH    = #{cash}
      ,UPD_DAY = NOW()
 WHERE 1=1
   AND USER_ID = #{userId}

mapper.insert:
INSERT INTO T_MOCK_HOLDING (
       USER_ID
      ,STOCK_ID
      ,QUANTITY
      ,AVG_PRICE
) VALUES (
       #{userId}
      ,#{stockId}
      ,#{quantity}
      ,#{avgPrice}
)
ON CONFLICT (USER_ID, STOCK_ID) DO UPDATE
   SET QUANTITY  = EXCLUDED.QUANTITY
      ,AVG_PRICE = EXCLUDED.AVG_PRICE
      ,UPD_DAY   = NOW()

mapper.delete:
DELETE FROM T_MOCK_HOLDING
 WHERE 1=1
   AND USER_ID  = #{userId}
   AND STOCK_ID = #{stockId}

